files.content:
.stepper{
  --stp-dot:var(--s-6);
  --stp-cur:var(--s-8);
  container-type:inline-size;
}
.stepper-list{
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
}
.stepper-step{
  flex:1 1 0;
  min-width:0;
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:center;
  text-align:center;
  gap:var(--s-2);
}
.stepper-step::after{
  content:"";
  position:absolute;
  top:calc(var(--stp-cur) / 2);
  left:50%;
  width:100%;
  height:var(--bw-2);
  background:repeating-linear-gradient(90deg,var(--obsidian-300) 0 var(--s-1),transparent var(--s-1) var(--s-2));
  transform:translateY(-50%);
}
.stepper-step:last-child::after{
  display:none;
}
.stepper-step.is-done::after{
  height:var(--bw-2);
  border:0;
  border-radius:var(--r-xs);
  background:var(--grad-progress);
  box-shadow:var(--sh-glow-soft);
}
.stepper-dot{
  position:relative;
  z-index:1;
  width:var(--stp-dot);
  height:var(--stp-dot);
  margin:calc((var(--stp-cur) - var(--stp-dot)) / 2) 0;
  border-radius:var(--r-full);
  display:grid;
  place-items:center;
  font-size:var(--t-caption);
  font-weight:600;
  color:var(--obsidian-300);
  background:var(--obsidian-800);
  box-shadow:inset 0 0 0 var(--bw-1) var(--obsidian-300);
}
.stepper-step.is-done .stepper-dot{
  background:var(--primary-500);
  box-shadow:none;
  color:var(--obsidian-950);
}
.stepper-step[aria-current="step"] .stepper-dot{
  width:var(--stp-cur);
  height:var(--stp-cur);
  margin:0;
  background:var(--grad-progress);
  box-shadow:var(--sh-glow);
  color:var(--obsidian-950);
  font-weight:700;
}
.stepper-step[aria-current="step"] .stepper-dot::after{
  content:"";
  position:absolute;
  inset:calc(-1 * var(--s-1));
  border-radius:var(--r-full);
  box-shadow:0 0 0 var(--bw-1) var(--primary-500);
  animation:stepper-pulse 2400ms var(--ease-standard) infinite;
}
.stepper-text{
  display:flex;
  flex-direction:column;
  align-items:inherit;
  gap:var(--s-0-5);
}
.stepper-sr-only{
  position:absolute;
  width:var(--s-px);
  height:var(--s-px);
  padding:0;
  margin:calc(-1 * var(--s-px));
  overflow:hidden;
  clip:rect(0,0,0,0);
  white-space:nowrap;
  border:0;
}
.stepper-label{
  font-size:var(--t-small);
  font-weight:400;
  color:var(--obsidian-300);
}
.stepper-meta{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
}
.stepper-step.is-done .stepper-label{
  font-weight:600;
  color:var(--obsidian-100);
}
.stepper-step[aria-current="step"] .stepper-label{
  font-weight:700;
  color:var(--primary-200);
}
.stepper-step[aria-current="step"] .stepper-meta{
  color:var(--primary-200);
}
.stepper[data-reveal] .stepper-step::after{
  opacity:0;
  transform:translateY(-50%) scaleX(0);
  transform-origin:left;
}
.stepper[data-reveal] .stepper-dot{
  opacity:0;
  transform:scale(0);
}
.stepper[data-reveal] .stepper-text{
  opacity:0;
  transform:translateY(var(--s-2));
}
.stepper-vertical .stepper-list{
  flex-direction:column;
  gap:var(--s-8);
}
.stepper-vertical .stepper-step{
  flex-direction:row;
  align-items:center;
  text-align:left;
  gap:var(--s-3);
}
.stepper-vertical .stepper-text{
  align-items:flex-start;
}
.stepper-vertical .stepper-dot{
  margin:0 calc((var(--stp-cur) - var(--stp-dot)) / 2);
}
.stepper-vertical .stepper-step::after{
  top:calc(var(--stp-cur) / 2);
  left:calc(var(--stp-cur) / 2);
  width:var(--bw-2);
  height:calc(100% + var(--s-8));
  background:repeating-linear-gradient(180deg,var(--obsidian-300) 0 var(--s-1),transparent var(--s-1) var(--s-2));
  transform:translateX(-50%);
}
.stepper-vertical .stepper-step.is-done::after{
  width:var(--bw-2);
  border:0;
  background:linear-gradient(180deg,var(--primary-200),var(--primary-500));
}
.stepper-vertical[data-reveal] .stepper-step::after{
  transform:translateX(-50%) scaleY(0);
  transform-origin:top;
}
@container (max-width: 480px){
  .stepper-list{
    flex-direction:column;
    gap:var(--s-8);
  }
  .stepper-step{
    flex-direction:row;
    align-items:center;
    text-align:left;
    gap:var(--s-3);
  }
  .stepper-text{
    align-items:flex-start;
  }
  .stepper-dot{
    margin:0 calc((var(--stp-cur) - var(--stp-dot)) / 2);
  }
  .stepper-step::after{
    top:calc(var(--stp-cur) / 2);
    left:calc(var(--stp-cur) / 2);
    width:var(--bw-2);
    height:calc(100% + var(--s-8));
    background:repeating-linear-gradient(180deg,var(--obsidian-300) 0 var(--s-1),transparent var(--s-1) var(--s-2));
    transform:translateX(-50%);
  }
  .stepper-step.is-done::after{
    width:var(--bw-2);
    height:calc(100% + var(--s-8));
    border:0;
    background:linear-gradient(180deg,var(--primary-200),var(--primary-500));
  }
  .stepper[data-reveal] .stepper-step::after{
    transform:translateX(-50%) scaleY(0);
    transform-origin:top;
  }
}
@media (prefers-reduced-motion: reduce){
  .stepper[data-reveal] .stepper-step::after, .stepper[data-reveal] .stepper-dot, .stepper[data-reveal] .stepper-text{
    opacity:1;
    transition:none;
  }
  .stepper[data-reveal] .stepper-dot, .stepper[data-reveal] .stepper-text{
    transform:none;
  }
  .stepper[data-reveal] .stepper-step::after{
    transform:translateY(-50%);
    transition:none;
  }
  .stepper-vertical[data-reveal] .stepper-step::after{
    transform:translateX(-50%);
  }
  .stepper-step[aria-current="step"] .stepper-dot::after{
    animation:none;
    transform:none;
    opacity:0.4;
  }
}
